-- Initial schema for paab (docs/design.md sections 1, 3 and 4).
--
-- Conventions
--   * Timestamps are INTEGER UNIX milliseconds in UTC. The database never
--     generates them. Callers pass every timestamp in, so that time can be
--     injected in tests.
--   * Entity IDs are TEXT UUIDs generated by the caller. audit_log uses an
--     autoincrement INTEGER so that entries keep their insertion order.
--   * Token plaintext is never stored. tokens.token_hash holds a hash only.

CREATE TABLE agents (
	id TEXT PRIMARY KEY NOT NULL,
	owner_id TEXT NOT NULL,
	name TEXT NOT NULL UNIQUE,
	description TEXT NOT NULL,
	status TEXT NOT NULL CHECK (status IN ('active', 'suspended')),
	daily_question_limit INTEGER NOT NULL CHECK (daily_question_limit >= 0),
	created_at INTEGER NOT NULL
) STRICT;

-- A token is valid while revoked_at IS NULL.
CREATE TABLE tokens (
	id TEXT PRIMARY KEY NOT NULL,
	agent_id TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
	token_hash TEXT NOT NULL UNIQUE,
	purpose TEXT NOT NULL CHECK (purpose IN ('participant', 'admin', 'unread_count')),
	created_at INTEGER NOT NULL,
	revoked_at INTEGER
) STRICT;

-- At most one valid token per agent and purpose. Reissuing must revoke the
-- old token before (or in the same batch as) inserting the new one.
CREATE UNIQUE INDEX tokens_active_idx
	ON tokens (agent_id, purpose)
	WHERE revoked_at IS NULL;

CREATE TABLE categories (
	id TEXT PRIMARY KEY NOT NULL,
	name TEXT NOT NULL UNIQUE
) STRICT;

-- A row allows from_agent_id to ask to_agent_id about category_id. Anything
-- not listed is denied. The primary key also serves lookups by sender.
CREATE TABLE allow_rules (
	from_agent_id TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
	to_agent_id TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
	category_id TEXT NOT NULL REFERENCES categories (id) ON DELETE CASCADE,
	created_at INTEGER NOT NULL,
	PRIMARY KEY (from_agent_id, to_agent_id, category_id),
	CHECK (from_agent_id <> to_agent_id)
) STRICT;

-- Questions, answers and rejections.
--
-- status describes the lifecycle of a question:
--   pending   waiting for an answer (deliverable to the recipient)
--   answered  the recipient answered
--   declined  the recipient declined
--   expired   nobody answered before expires_at
--   blocked   the bridge rejected it, so it is never delivered
-- Answers and rejections have no lifecycle of their own and always use
--   sent      deliverable to the asker
--
-- A question the bridge rejected still gets a row (status = 'blocked') so
-- that it counts toward the daily question limit of the sender and has an ID
-- the rejection can refer to. Such a row may lack a recipient or a category
-- when the requested one does not exist. A rejection may lack a sender for
-- the same reason.
CREATE TABLE messages (
	id TEXT PRIMARY KEY NOT NULL,
	kind TEXT NOT NULL CHECK (kind IN ('question', 'answer', 'rejection')),
	from_agent_id TEXT REFERENCES agents (id),
	to_agent_id TEXT REFERENCES agents (id),
	category_id TEXT REFERENCES categories (id),
	body TEXT,
	in_reply_to TEXT REFERENCES messages (id),
	status TEXT NOT NULL,
	created_at INTEGER NOT NULL,
	received_at INTEGER,
	expires_at INTEGER,
	body_deleted_at INTEGER,
	CHECK (
		(kind = 'question' AND status IN ('pending', 'answered', 'declined', 'expired', 'blocked'))
		OR (kind <> 'question' AND status = 'sent')
	),
	CHECK ((kind = 'question') = (in_reply_to IS NULL)),
	CHECK (from_agent_id IS NOT NULL OR kind = 'rejection'),
	CHECK (to_agent_id IS NOT NULL OR status = 'blocked'),
	CHECK (category_id IS NOT NULL OR status = 'blocked' OR kind = 'rejection'),
	CHECK (kind <> 'question' OR status = 'blocked' OR expires_at IS NOT NULL)
) STRICT;

-- Inbox fetch and unread count: undelivered messages by recipient and status.
CREATE INDEX messages_inbox_idx
	ON messages (to_agent_id, status, created_at)
	WHERE received_at IS NULL;

-- Daily question count per sender, including blocked questions.
CREATE INDEX messages_daily_questions_idx
	ON messages (from_agent_id, created_at)
	WHERE kind = 'question';

-- Expiry sweep over unanswered questions.
CREATE INDEX messages_expiry_idx
	ON messages (expires_at)
	WHERE status = 'pending';

-- One reply (answer or rejection) per question.
CREATE UNIQUE INDEX messages_reply_idx
	ON messages (in_reply_to)
	WHERE in_reply_to IS NOT NULL;

-- Audit log. Agent, category and message references are deliberately not
-- foreign keys, so that entries survive the deletion of what they refer to
-- and can record events that have no agent (failed authentication).
-- event_type and reason_code are validated in src/db/rows.ts rather than by
-- CHECK constraints, so that later stages can add values without rebuilding
-- the table. body stays NULL unless body recording is enabled.
CREATE TABLE audit_log (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	occurred_at INTEGER NOT NULL,
	event_type TEXT NOT NULL,
	from_agent_id TEXT,
	to_agent_id TEXT,
	category_id TEXT,
	outcome TEXT NOT NULL CHECK (outcome IN ('ok', 'denied', 'expired')),
	reason_code TEXT,
	message_id TEXT,
	body TEXT
) STRICT;

CREATE INDEX audit_log_occurred_at_idx ON audit_log (occurred_at);
